import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

/**
 * Test that a member cannot restore another member's soft-deleted todo.
 *
 * Verifies data isolation between members by ensuring that only the todo owner can perform restore operations on deleted todos. Member A creates and soft-deletes a todo, then Member B (a different registered member) attempts to restore it. The restore endpoint must reject the request with a 403 Forbidden error, confirming that cross-member access is properly blocked.
 *
 * Special attention is given to validating that the authorization check occurs before any restore logic, preventing unauthorized members from even discovering the existence of another member's todos through error messages or side effects.
 *
 * 1. Member A authenticates and registers a new member account.
 * 2. Member A creates a todo item with a random title.
 * 3. Member A soft-deletes the todo, moving it to trash.
 * 4. Member B authenticates as a separate member account.
 * 5. Member B attempts to restore Member A's soft-deleted todo using the todo ID.
 * 6. The restore endpoint rejects the request with 403 Forbidden error, enforcing strict data isolation.
 */
export async function test_api_todo_restore_unauthorized_member_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member A authenticates and registers
  const memberAConnection: api.IConnection = { host: connection.host };
  const memberA = await authorize_member_join(memberAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberA);
  // 2. Member A creates a todo
  const todo = await generate_random_todo_app_member_todos_create(
    memberAConnection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  typia.assert(todo);
  // 3. Member A soft-deletes the todo
  await api.functional.todoApp.member.todos.erase(memberAConnection, {
    todoId: todo.id,
  });
  // 4. Member B authenticates as a different member
  const memberBConnection: api.IConnection = { host: connection.host };
  const memberB = await authorize_member_join(memberBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberB);
  // 5. Member B attempts to restore Member A's todo - should fail with 403 Forbidden
  await TestValidator.httpError(
    "unauthorized member cannot restore another member's todo",
    403,
    () =>
      api.functional.todoApp.member.todos.restore(memberBConnection, {
        todoId: todo.id,
      }),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

/**
 * Test that restoring an already active todo is rejected with 409 Conflict.
 *
 * Validates that attempting to restore a todo that is not in trash state (i.e., a todo with deleted_at being null) is rejected by the system. After a member creates an active todo, directly calling the restore endpoint without soft-deleting the todo first should result in a 409 Conflict error, indicating the todo cannot be restored because it is already active. The system must reject this invalid state transition to prevent unintended side effects.
 *
 * 1. Member registers and authenticates.
 * 2. Member creates a todo that remains in active state (deleted_at is null).
 * 3. Member attempts to restore the active todo without soft-deleting it.
 * 4. Validates 409 Conflict error is thrown.
 * 5. Validates the todo was in active state with deleted_at remaining null.
 */
export async function test_api_todo_restore_already_active_todo(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, { body: undefined });
  // 2. Create an active todo (deleted_at is null by default)
  const todo =
    await generate_random_todo_app_member_todos_create(memberConnection);
  typia.assert(todo);
  // 3. Validate todo is in active state (deleted_at is null)
  TestValidator.equals(
    "todo is active with deleted_at null",
    todo.deleted_at,
    null,
  );
  // 4. Attempt to restore the already active todo - should throw 409 Conflict
  await TestValidator.httpError(
    "restoring active todo returns 409 Conflict",
    409,
    async () =>
      await api.functional.todoApp.member.todos.restore(memberConnection, {
        todoId: todo.id,
      }),
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

/**
 * Test permanent deletion of a todo from trash with cascade deletion of edit history.
 *
 * Validates the complete lifecycle of a todo from creation through permanent deletion. The workflow authenticates a member, creates a todo, edits it to generate edit history entries, soft-deletes the todo to move it to trash, and finally permanently deletes it from the trash. The permanent deletion cascades to remove all associated edit history entries within a database transaction.
 *
 * 1. Authenticate a new member to establish ownership context.
 * 2. Create a todo with title and optional description.
 * 3. Edit the todo to generate edit history entries for cascade validation.
 * 4. Soft-delete the todo to move it into the trash.
 * 5. Permanently delete the todo from trash, cascading edit history deletion.
 */
export async function test_api_todo_permanent_deletion_from_trash(
  connection: api.IConnection,
) {
  // 1. Member authentication
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies DeepPartial<ITodoAppMember.IJoin>,
  });
  // 2. Create a todo
  const todo =
    await generate_random_todo_app_member_todos_create(memberConnection);
  typia.assert(todo);
  // 3. Edit the todo to generate edit history entries
  const updatedTodo = await api.functional.todoApp.member.todos.update(
    memberConnection,
    {
      todoId: todo.id,
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
      } satisfies ITodoAppTodo.IUpdate,
    },
  );
  typia.assert(updatedTodo);
  // 4. Soft-delete the todo to move it to trash
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId: todo.id,
  });
  // 5. Permanently delete the todo from trash
  await api.functional.todoApp.member.todos.permanent_delete.permanentErase(
    memberConnection,
    {
      todoId: todo.id,
    },
  );
}

